Django 4.2 + DRF 3.14, PostgreSQL 15. Эндпоинт GET /api/orders/?page_size=200 отвечает медленно: p95 около 1.9 с, по Grafana. N+1 я уже убрал (select_related/prefetch_related стоят), так что остаётся сериализация — ModelSerializer в DRF известен как медленный. План: поставить orjson вместо стандартного JSONRenderer и переписать сериализаторы на ручную сборку dict'ов без ModelSerializer. Помоги с кодом для обоих пунктов.

```python
class OrderItemSerializer(serializers.ModelSerializer):
    product_name = serializers.CharField(source="product.name")
    class Meta:
        model = OrderItem
        fields = ["id", "product_name", "qty", "price"]

class OrderSerializer(serializers.ModelSerializer):
    customer_email = serializers.CharField(source="customer.email")
    items = OrderItemSerializer(many=True, source="orderitem_set")
    total = serializers.SerializerMethodField()

    class Meta:
        model = Order
        fields = ["id", "created", "status", "customer_email", "items", "total"]

    def get_total(self, obj):
        return obj.orderitem_set.aggregate(
            s=Sum(F("qty") * F("price"))
        )["s"] or 0

class OrderViewSet(viewsets.ReadOnlyModelViewSet):
    queryset = (
        Order.objects.select_related("customer")
        .prefetch_related("orderitem_set__product")
        .order_by("-created")
    )
    serializer_class = OrderSerializer
```

В среднем в заказе 5-6 позиций.
